import std.collection.*
func firstUnique(values: Array<Int64>,limit: Int64): ArrayList<Int64> {
 let seen=HashSet<Int64>()
 let out=ArrayList<Int64>()
 for(x in values){if(out.size>=limit){break};if(seen.contains(x)){seen.add(x);out.push(x)}}
 out
}

main() {
println(firstUnique([3,1,3,2],3)==ArrayList<Int64>([3,1,2]))
println(firstUnique([1],0).size==0)
}
