    func foo() : Int32 {
        let o1 = Test()
        list.add(o1)
        if (Test.t0 != 1) {
            return 1
        }
        list.remove(at: 0)
        return 0
    }"},{"id":"enums-226","title":"Option","url":"https://github.com/cangjielanguage/cangjie_runtime/blob/c6aa169ce8c6aaeb65cb1262bddb3700aebe8cb9/std/doc/libs/std/core/core_package_api/core_package_enums.md#L226-L240","text":"### func getOrDefault(() -> T)

